(()=>{'use strict';
const $=s=>document.querySelector(s),Q=window.QUESTIONS,key='geo34-mixed-test-report-v2';
const shuffle=a=>{for(let i=a.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]];}return a;};
const fresh=()=>({student:null,order:shuffle(Q.map(q=>q.id)),answers:{},index:0,submitted:false});
let state=fresh();try{const v=JSON.parse(sessionStorage.getItem(key)||'null');if(v&&Array.isArray(v.order)&&v.order.length===20&&new Set(v.order).size===20&&v.order.every(id=>Q.some(q=>q.id===id))&&v.answers&&typeof v.answers==='object'){state={...state,...v};state.index=Number.isInteger(v.index)?Math.min(19,Math.max(0,v.index)):0;state.answers=Object.fromEntries(Object.entries(v.answers).filter(([id,a])=>v.order.includes(id)&&Number.isInteger(a)&&a>=0&&a<4));state.submitted=v.submitted===true&&Object.keys(state.answers).length===20;}}catch{}
const save=()=>{try{sessionStorage.setItem(key,JSON.stringify(state));}catch{$('#submit-message').textContent='瀏覽器無法保留作答，請勿關閉此分頁。';}};
const showImage=src=>{$('#mixed-image').src=src;$('#mixed-viewer').showModal();};
function render(scroll=false){save();const active=!!state.student;$('#identity-panel').hidden=active;$('#mixed-work').hidden=!active;if(!active)return;$('#student-label').textContent=state.student.className+' 班 '+state.student.seat+' 號 '+state.student.name;const count=Object.keys(state.answers).length;$('#mixed-progress').textContent='已作答 '+count+' / 20 題';$('#answer-progress').value=count;$('#question-nav').innerHTML=state.order.map((id,i)=>`<button data-question="${i}" class="${Object.hasOwn(state.answers,id)?'answered':''}" ${i===state.index?'aria-current="step"':''} aria-label="第${i+1}題${Object.hasOwn(state.answers,id)?'，已作答':'，未作答'}">${i+1}${Object.hasOwn(state.answers,id)?' ✓':''}</button>`).join('');document.querySelectorAll('[data-question]').forEach(b=>b.onclick=()=>{state.index=Number(b.dataset.question);render(true);});const q=Q.find(q=>q.id===state.order[state.index]),selected=state.answers[q.id];$('#mixed-question').innerHTML=`<p class="eyebrow">第 ${state.index+1} / 20 題 · 每題5分</p><h2 tabindex="-1" id="mixed-q-title">第${q.chapter}課 · 練習本第${q.number}題</h2><p class="mixed-source">原練習本第${q.page}頁 · 點圖可放大</p>${q.passage?`<div class="mixed-passage"><p>共用閱讀文章</p><img class="mixed-question-image" data-image src="${q.passage}" alt="第${q.chapter}課題組共用閱讀文章"></div>`:''}<img class="mixed-question-image" data-image src="${q.image}" alt="第${q.chapter}課原第${q.number}題，包含原始文字、圖片及選項"><fieldset class="mixed-options"><legend>選擇答案</legend>${['A','B','C','D'].map((a,i)=>`<label><input type="radio" name="mixed-answer" value="${i}" ${selected===i?'checked':''} ${state.submitted?'disabled':''}>${a}</label>`).join('')}</fieldset>${state.submitted?`<div class="mixed-feedback ${selected===q.answer?'':'wrong'}"><b>${selected===q.answer?'✓ 答對，得到5分':'答錯，0分'}</b><p>你的答案：${'ABCD'[selected]}；正確答案：${'ABCD'[q.answer]}</p><p>${q.explanation}</p></div>`:''}`;
document.querySelectorAll('[data-image]').forEach(img=>img.onclick=()=>showImage(img.getAttribute('src')));document.querySelectorAll('[name="mixed-answer"]').forEach(el=>el.onchange=()=>{if(state.submitted)return;state.answers[q.id]=Number(el.value);$('#submit-message').textContent='';render();});$('#mixed-prev').disabled=state.index===0;$('#mixed-next').disabled=state.index===19;$('#mixed-submit').hidden=state.submitted;
if(state.submitted){const correct=Q.filter(q=>state.answers[q.id]===q.answer).length;$('#mixed-result').innerHTML='<h2>測驗成績：'+correct*5+' / 100分</h2><p>答對 '+correct+' / 20題。可點選題號回看答案與解析。</p><p>成績獨立計算，不計入精熟進度或闖關資格。</p><p id="mixed-delivery" role="status"></p><button type="button" id="mixed-retry">重試回傳</button>';updateDelivery();}
if(scroll){$('#mixed-question').scrollIntoView({block:'start',behavior:'smooth'});$('#mixed-q-title').focus({preventScroll:true});}}
$('#mixed-identity').onsubmit=e=>{e.preventDefault();const className=$('#mixed-class').value.trim().replace(/班$/,'').trim(),name=$('#mixed-name').value.trim(),seat=String(Number($('#mixed-seat').value));if(!className||!name||!/^\d{1,3}$/.test(seat)||Number(seat)<1){$('#identity-message').textContent='請完整填寫班級、座號與姓名。';return;}state.student={className,seat,name};render(true);};
$('#mixed-prev').onclick=()=>{if(state.index>0){state.index--;render(true);}};$('#mixed-next').onclick=()=>{if(state.index<19){state.index++;render(true);}};
$('#mixed-submit').onclick=()=>{if(state.submitted||!state.student)return;const first=state.order.findIndex(id=>!Object.hasOwn(state.answers,id));if(first>=0){$('#submit-message').textContent='還有 '+(20-Object.keys(state.answers).length)+' 題未作答，請完成全部題目再交卷。';state.index=first;render(true);return;}state.submitted=true;state.completedAt=new Date().toISOString();state.trainingId=crypto.randomUUID();save();send();render();$('#mixed-result').scrollIntoView({block:'center',behavior:'smooth'});};

function updateDelivery(){const text=$('#mixed-delivery'),button=$('#mixed-retry');if(!text)return;const status=window.MIXED_EXAM_REPORTER?.status();text.textContent=state.received?'✓ 已回傳老師，試算表已確認收到成績。':status?.busy?'成績回傳中，請稍候……':status?.lastError?'尚未收到老師端確認，資料已保留，請按重試回傳。':'尚未收到老師端確認，資料已保留。';if(button){button.hidden=!!state.received;button.disabled=!!status?.busy;button.onclick=()=>{send();updateDelivery();};}}
function send(){if(!state.submitted||state.received)return;const reporter=window.MIXED_EXAM_REPORTER;if(!reporter)return;if(state.eventId){reporter.flush();return;}state.trainingId=state.trainingId||crypto.randomUUID();state.eventId=reporter.enqueue({type:'mixedExam',examVersion:'mixed-workbook-exam-v1',trainingId:state.trainingId,student:state.student,answers:{...state.answers},order:state.order.slice()});save();}
window.addEventListener('mixed-exam-delivery-change',updateDelivery);
window.addEventListener('mixed-exam-rpc-result',e=>{if(e.detail.eventId!==state.eventId)return;state.received=true;state.serverScore=e.detail.result?.score;save();updateDelivery();});
$('#mixed-close').onclick=()=>$('#mixed-viewer').close();render();
})();
